    ea4_pgi_gmom_m = EA4_Meta_Mother_PGI,
    ea4_pgi_gmom_m_imp = EA4_Meta_Mother_PGI_Imp,
    ea4_pgi_gdad_m = EA4_Meta_Father_PGI,
    ea4_pgi_gdad_m_imp = EA4_Meta_Father_PGI_Imp,
    ea4_pgi_sum_m = EA4_Meta_PGI_Parental,

    # EA3 Noncog PGI variables for maternal grandparents
    ea3noncog_pgi_gmom_m = EA3NonCog_Mother_PGI,
    ea3noncog_pgi_gmom_m_imp = EA3NonCog_Mother_PGI_Imp,
    ea3noncog_pgi_gdad_m = EA3NonCog_Father_PGI,
    ea3noncog_pgi_gdad_m_imp = EA3NonCog_Father_PGI_Imp,
    ea3noncog_pgi_sum_m = EA3NonCog_PGI_Parental,

    # EA3 Cog PGI variables for maternal grandparents
    ea3cog_pgi_gmom_m = EA3Cog_Mother_PGI,
    ea3cog_pgi_gmom_m_imp = EA3Cog_Mother_PGI_Imp,
    ea3cog_pgi_gdad_m = EA3Cog_Father_PGI,
    ea3cog_pgi_gdad_m_imp = EA3Cog_Father_PGI_Imp,
    ea3cog_pgi_sum_m = EA3Cog_PGI_Parental
  )

# Extended family with father as focal parent by merging by dad_id
within_fam_ea_pgi <- merge(within_fam_ea_pgi, ea_pgi, by.x = "dad_id", by.y = "project_pseudo_id", all.x = TRUE)

within_fam_ea_pgi <- within_fam_ea_pgi %>%
  select(-EA4_Meta_PGI, -EA3NonCog_PGI, -EA3Cog_PGI,
  -PC1, -PC2, -PC3, -PC4, -PC5, -PC6, -PC7, -PC8, -PC9, -PC10) %>%
  rename(
