    ea3noncog_pgi_sum_f = EA3NonCog_PGI_Parental,

    # EA3 Cog PGI variables for paternal grandparents
    ea3cog_pgi_gmom_f = EA3Cog_Mother_PGI,
    ea3cog_pgi_gmom_f_imp = EA3Cog_Mother_PGI_Imp,
    ea3cog_pgi_gdad_f = EA3Cog_Father_PGI,
    ea3cog_pgi_gdad_f_imp = EA3Cog_Father_PGI_Imp,
    ea3cog_pgi_sum_f = EA3Cog_PGI_Parental
  )

# Print the number of rows
print(nrow(within_fam_ea_pgi)) #80090

