## GENERATE FOCAL PGI VARIABLES FOR PEDIGREE ANALYSES

# Generalized function to create focal, non-focal, and gender-neutral PGI variables including imputed values for non-focal PGIs
create_focal_pgi <- function(data, pgi_type, pgi_m, pgi_m_imp, pgi_f, pgi_f_imp, pgi_sum_m, pgi_sum_f) {
  
  data <- data %>%
    mutate(
      # Mother is considered a focal parent if both her PGI and maternal grandparental PGI are present
      !!paste0(pgi_type, "_pgi_m_focal") := if_else(!is.na(!!sym(pgi_m)) & !is.na(!!sym(pgi_sum_m)), !!sym(pgi_m), NA_real_),
      !!paste0(pgi_type, "_pgi_sum_m_focal") := if_else(!is.na(!!sym(pgi_m)) & !is.na(!!sym(pgi_sum_m)), !!sym(pgi_sum_m), NA_real_),
      
      # Father is considered a focal parent if both his PGI and paternal grandparental PGI are present
      !!paste0(pgi_type, "_pgi_f_focal") := if_else(!is.na(!!sym(pgi_f)) & !is.na(!!sym(pgi_sum_f)), !!sym(pgi_f), NA_real_),
      !!paste0(pgi_type, "_pgi_sum_f_focal") := if_else(!is.na(!!sym(pgi_f)) & !is.na(!!sym(pgi_sum_f)), !!sym(pgi_sum_f), NA_real_),
      
      # If the mother is focal, father becomes non-focal, using imputed if available
      !!paste0(pgi_type, "_pgi_f_nonfocal") := if_else(!is.na(!!sym(pgi_m)) & !is.na(!!sym(pgi_sum_m)), 
                                                       coalesce(!!sym(pgi_f), !!sym(pgi_f_imp)), NA_real_),
      
      # If the father is focal, mother becomes non-focal, using imputed if available
      !!paste0(pgi_type, "_pgi_m_nonfocal") := if_else(!is.na(!!sym(pgi_f)) & !is.na(!!sym(pgi_sum_f)), 
                                                       coalesce(!!sym(pgi_m), !!sym(pgi_m_imp)), NA_real_),
      
      # Gender-neutral focal PGI: Either parent can be focal
      !!paste0(pgi_type, "_pgi_focal") := coalesce(!!sym(paste0(pgi_type, "_pgi_m_focal")), !!sym(paste0(pgi_type, "_pgi_f_focal"))),
      !!paste0(pgi_type, "_pgi_sum_focal") := coalesce(!!sym(paste0(pgi_type, "_pgi_sum_m_focal")), !!sym(paste0(pgi_type, "_pgi_sum_f_focal"))),
      
      # Gender-neutral non-focal PGI: The non-focal parent if the other parent is focal, using imputed if available
      !!paste0(pgi_type, "_pgi_nonfocal") := coalesce(!!sym(paste0(pgi_type, "_pgi_f_nonfocal")), !!sym(paste0(pgi_type, "_pgi_m_nonfocal")))
    )
  
  return(data)
}

# List of PGI types and their corresponding column names (including imputed PGIs)
pgi_info <- list(
  list(type = "ea4", pgi_m = "ea4_pgi_m", pgi_m_imp = "ea4_pgi_m_imp", pgi_f = "ea4_pgi_f", pgi_f_imp = "ea4_pgi_f_imp", pgi_sum_m = "ea4_pgi_sum_m", pgi_sum_f = "ea4_pgi_sum_f"),
  list(type = "ea3noncog", pgi_m = "ea3noncog_pgi_m", pgi_m_imp = "ea3noncog_pgi_m_imp", pgi_f = "ea3noncog_pgi_f", pgi_f_imp = "ea3noncog_pgi_f_imp", pgi_sum_m = "ea3noncog_pgi_sum_m", pgi_sum_f = "ea3noncog_pgi_sum_f"),
  list(type = "ea3cog", pgi_m = "ea3cog_pgi_m", pgi_m_imp = "ea3cog_pgi_m_imp", pgi_f = "ea3cog_pgi_f", pgi_f_imp = "ea3cog_pgi_f_imp", pgi_sum_m = "ea3cog_pgi_sum_m", pgi_sum_f = "ea3cog_pgi_sum_f")
)

# Apply the function for all PGI types using a loop
for (pgi in pgi_info) {
  within_fam_ea_pgi <- create_focal_pgi(within_fam_ea_pgi, pgi$type, pgi$pgi_m, pgi$pgi_m_imp, pgi$pgi_f, pgi$pgi_f_imp, pgi$pgi_sum_m, pgi$pgi_sum_f)
}

