	ea3noncog_pgi_focal, ea3noncog_pgi_sum_focal, ea3noncog_pgi_nonfocal,
	ea3noncog_pgi_m_focal, ea3noncog_pgi_sum_m_focal, ea3noncog_pgi_f_nonfocal,
	ea3noncog_pgi_f_focal, ea3noncog_pgi_sum_f_focal, ea3noncog_pgi_m_nonfocal,
	
    # EA3 Cog PGI Indices
    ea3cog_pgi, ea3cog_pgi_m, ea3cog_pgi_f, ea3cog_pgi_m_imp, ea3cog_pgi_f_imp, ea3cog_pgi_sum,
    ea3cog_pgi_gmom_m, ea3cog_pgi_gdad_m, ea3cog_pgi_gmom_m_imp, ea3cog_pgi_gdad_m_imp, ea3cog_pgi_sum_m,
    ea3cog_pgi_gmom_f, ea3cog_pgi_gdad_f, ea3cog_pgi_gmom_f_imp, ea3cog_pgi_gdad_f_imp, ea3cog_pgi_sum_f,
	ea3cog_pgi_focal, ea3cog_pgi_sum_focal, ea3cog_pgi_nonfocal,
	ea3cog_pgi_m_focal, ea3cog_pgi_sum_m_focal, ea3cog_pgi_f_nonfocal,
	ea3cog_pgi_f_focal, ea3cog_pgi_sum_f_focal, ea3cog_pgi_m_nonfocal,

